# Ключи приложения Шикимори (OAuth) — только из локального shikimori.local.json в корне репозитория (он в .gitignore).
# Попадают в сгенерированный проект (тоже в .gitignore), в Info.plist остаются только ссылки $(SHIKI_…).
import json,re
_sk=p.parent/'shikimori.local.json'
_s=json.loads(_sk.read_text()) if _sk.exists() else {}
_ok=lambda v:isinstance(v,str) and re.fullmatch(r'[A-Za-z0-9_\-]{8,128}',v)
shiki=f'SHIKI_CLIENT_ID="{_s["client_id"]}"; SHIKI_CLIENT_SECRET="{_s["client_secret"]}"; ' if _ok(_s.get('client_id')) and _ok(_s.get('client_secret')) else 'SHIKI_CLIENT_ID=""; SHIKI_CLIENT_SECRET=""; '
links='$(inherited) -ObjC -lc++ -lxml2 -lz -lbz2 -liconv -framework QuartzCore -framework CoreText -framework AVFoundation -framework Security -framework CFNetwork -framework AudioToolbox -framework OpenGLES -framework CoreGraphics -framework VideoToolbox -framework CoreMedia'
for key,name in [('tdbg','Debug'),('trel','Release')]:add(key,f'isa=XCBuildConfiguration; name={name}; buildSettings={{'+('SWIFT_ACTIVE_COMPILATION_CONDITIONS=DEBUG; SWIFT_OPTIMIZATION_LEVEL="-Onone"; ' if name=='Debug' else 'SWIFT_OPTIMIZATION_LEVEL="-O"; ENABLE_DEBUG_DYLIB=NO; ENABLE_PREVIEWS=NO; SWIFT_COMPILATION_MODE=wholemodule; ')+shiki+f'ASSETCATALOG_COMPILER_APPICON_NAME=AppIcon; PRODUCT_BUNDLE_IDENTIFIER=com.resvvt.nightanime.ios; PRODUCT_NAME="Night Anime"; INFOPLIST_FILE=NightAnime/Info.plist; TARGETED_DEVICE_FAMILY="1,2"; SWIFT_VERSION=5.0; CODE_SIGNING_ALLOWED=NO; ENABLE_BITCODE=NO; OTHER_LDFLAGS="{links}"; LD_RUNPATH_SEARCH_PATHS="$(inherited) @executable_path/Frameworks";}};')
(p/'NightAnime.xcodeproj/project.pbxproj').write_text('// !$*UTF8*$!\n{archiveVersion=1;classes={};objectVersion=56;objects={\n'+'\n'.join(k+'={'+v+'};' for k,v in obj.items())+'\n};rootObject='+I('project')+';}\n')
